export declare const typeDefs = "\n  type User {\n    id: ID!\n    email: String!\n    name: String!\n  }\n\n  type Character {\n    id: Int!\n    name: String!\n    gender: String!\n    culture: String!\n    born: String!\n    titles: [String!]!\n    tvSeries: [String!]!\n    playedBy: [String!]!\n    imageUrl: String\n    died: String\n    alive: Boolean\n    status: String\n    aliases: [String!]\n    books: [String!]\n    povBooks: [String!]\n  }\n\n  type CharacterPage {\n    page: Int!\n    pageSize: Int!\n    hasNext: Boolean!\n    hasPrevious: Boolean!\n    results: [Character!]!\n  }\n\n  type Favorite {\n    id: ID!\n    characterId: Int!\n    characterName: String!\n    createdAt: String!\n  }\n\n  type PageViewSummary {\n    path: String!\n    views: Int!\n  }\n\n  type Query {\n    me: User\n    characters(page: Int = 1, pageSize: Int = 9, search: String): CharacterPage!\n    character(id: Int!): Character\n    favorites: [Favorite!]!\n    analyticsSummary: [PageViewSummary!]!\n  }\n\n  type Mutation {\n    addFavorite(characterId: Int!): Favorite!\n    removeFavorite(characterId: Int!): Boolean!\n    trackPageView(path: String!): Boolean!\n  }\n";
